"""Тесты для модуля boardcam.sketch."""

import os
import unittest
from boardcam import sketch


class TestSketch(unittest.TestCase):

    def test_clean_scad_code(self):
        # 1. С markdown fence ```openscad
        raw1 = "```openscad\nmodule test() { cube([10, 10, 10]); }\ntest();\n```"
        self.assertEqual(sketch.clean_scad_code(raw1), "module test() { cube([10, 10, 10]); }\ntest();")

        # 2. С простым ```
        raw2 = "```\n$fn=32;\n```"
        self.assertEqual(sketch.clean_scad_code(raw2), "$fn=32;")

        # 3. Чистый код без fence
        raw3 = "circle(r=10);"
        self.assertEqual(sketch.clean_scad_code(raw3), "circle(r=10);")

    def test_clean_b64(self):
        # С префиксом data:image/jpeg;base64,...
        raw1 = "data:image/jpeg;base64,aGVsbG8="
        self.assertEqual(sketch._clean_b64(raw1), "aGVsbG8=")

        # С префиксом png
        raw2 = "data:image/png;base64,d29ybGQ="
        self.assertEqual(sketch._clean_b64(raw2), "d29ybGQ=")

        # Чистый base64
        raw3 = "c29tZXRoaW5n"
        self.assertEqual(sketch._clean_b64(raw3), "c29tZXRoaW5n")

    def test_get_shape_info(self):
        # Существующий leaf
        info = sketch.get_shape_info("leaf", "shapes")
        self.assertTrue(info["exists"])
        self.assertGreater(info["mtime"], 0)
        self.assertGreater(info["size"], 0)

        # Несуществующий
        info_missing = sketch.get_shape_info("non_existent_xyz", "shapes")
        self.assertFalse(info_missing["exists"])
        self.assertEqual(info_missing["mtime"], 0)
        self.assertEqual(info_missing["size"], 0)

    def test_get_available_models_fallback(self):
        # С фиктивным портом (проверка устойчивости к недоступному Ollama)
        models = sketch.get_available_models("http://127.0.0.1:54321", deepseek_api_key="sk-test")
        self.assertEqual(len(models), 1)
        self.assertEqual(models[0]["id"], "deepseek-flash")
        self.assertEqual(models[0]["provider"], "deepseek")


if __name__ == "__main__":
    unittest.main()
